    "key": [
      "赛9:6-7",
      "赛11:1-2",
      "路1:32-33"
    ],
    "one": "在黑暗最重的地方，神放下的不是一支军队，是一个婴孩；而他的名字长到没有人能一次说完。",
    "avoid": "9:6 的名号在犹太释经传统中多读作对大卫王朝君王的尊称组合，基督徒读法则读作对弥赛亚神性的宣告；两种读法并列，不要替读者裁判。",
