    "key": [
      "赛6:2-3",
      "赛6:6-7"
    ],
    "one": "他们先遮住自己，再呼喊「圣哉、圣哉、圣哉」；洁净以赛亚的，是其中一位从坛上取来的红炭。",
    "avoid": "圣经没有说撒拉弗有几个；「六个翅膀」是经文明确给出的数字，不要与基路伯等其他活物混淆。",
