    "one": "他一生强盛，却因擅自进殿烧香而长了大麻风；本章只留下他驾崩的那一年，作为整卷书最著名的异象的背景时间。",
    "avoid": "他在列王纪又称「亚撒利雅」，是同一人；不要与本书第 1 章列出的四位王混为一代人。",
