    "one": "一夜之间，两座城只剩名字；他们的财物带得走，水带不走——宁林的水先干，青绿之物一无所有。",
    "avoid": "摩押是城邦与群体，不是某一位君主；「亚珥、基珥」是城名不是人名。也别把「摩押」与后来的摩押地（现代约旦东部）简单划等号。",
