    "one": "他带着七十口人下埃及，本以为只是投奔一位亲戚；七十人后来成了一整个民族，而这一切是他在异乡多年之后就挂念的事。",
    "avoid": "不要把出 1 的家谱读成家谱学；它的功能是把「以色列众子」这个整体带进埃及，好让 1–15 章的压迫与拯救有一个具体的主体。",
