    "one": "他先造方舟用了许多年，没有人相信；等水来的时候，全家只有他这一只船是干的。洪水过后，神给他的第一样东西不是解释，是可以吃的肉。",
    "avoid": "「方舟」（teva）在旧约别处指普通的箱子或船（如赛 23:1 的基西拉船），本章讲的仍是 6–8 章那只方舟的延续；9:6「凡流人血的，他的血也必被人所流」是刑事条例，9:4 的禁食血是饮食条例，两条领域不同，不要混成一条。",
    "tags": [
      "旧约",
      "人物",
      "先祖"
    ],
    "chapters": [
      "gen-09"
    ]
