    "one": "他受命把一件说不出口的事讲成条例：身体流血使人不洁净，而触血的人要负责。",
    "avoid": "本章讲的是礼仪上的不洁净，不是道德上的定罪；「漏症」指身体的不洁分泌物，不要写成性病。",
