    "relation": "16:1 全会众从以琳起行，第二个月十五日到汛的旷野；16:2 向摩西、亚伦发怨言；16:31–33「他们就称那地方为玛拿」（吗哪）；16:35「以色列人用它四十年的工夫在旷野吃到吗哪」",
