    "relation": "21:2–6：买来的希伯来男仆服事六年，第七年可「白白地出去」；有妻可同出，生了儿女则妻儿归主人；21:5 他可「明说」爱主人与家人、不愿自由，主人便要带他到审判官面前、靠着门框用锥子穿耳，他就「永远服事主人」；21:26–27 若主人打坏他一只眼或一个牙，他要因这眼或牙「放他去得以自由」；21:16 另禁止蓄意扣留被卖的人",
