    "avoid": "不要把他读成「圣经认可奴役」的证据——本章的条款处处限制主人、处处给他出路（第七年释放、诡诈即失权、不得转卖外邦人、打坏眼牙即得自由）；也不要把这一类仆人与以赛亚书 42 章、52–53 章的「仆人之歌」里的受苦之仆直接划等号：前者是律法里的身份，后者是救赎的形像。",
