    "desc": "约西亚八岁登基，作王三十一年，行耶和华眼中看为正的事，行他祖大卫一切所行的，不偏左右。他在位第十八年，差遣人修理耶和华的殿，大祭司希勒家发现了律法书。约西亚听见律法书上的话，便撕裂衣服，差遣人求问耶和华。女先知户勒大预言这地必受审判，但约西亚因心里敬服、在神面前自卑，必平平安安归到坟墓。",
