    "desc": "约西亚进行了旧约中最彻底的宗教改革——废去偶像、污秽邱坛、拆毁从所罗门到玛拿西历代所筑的坛、守逾越节。圣经评价说：「在约西亚以前没有王像他尽心、尽性、尽力的归向耶和华，遵行摩西的一切律法；在他以后也没有兴起一个王像他。」然而，他在米吉多被埃及王法老尼哥杀死，改革随着他的死亡而结束。",
    "avoid": "不要与 2ki-22 的约西亚卡混淆（同一人物不同章节）；不要因为约西亚的改革就认为犹大不会被掳——审判仍然临到。",
    "one": "约西亚进行了旧约中最彻底的宗教改革——废去偶像、污秽邱坛、拆毁从所罗门到玛拿西历代所筑的坛、守逾越节。"
