    "desc": "西底家是巴比伦王立的傀儡王（24:17），但他背叛了巴比伦，投靠埃及。尼布甲尼撒围困耶路撒冷十八个月，城被攻破后，西底家夜间逃跑，在耶利哥平原被追上。他的众子在他眼前被杀，他的眼睛被剜出，用铜链锁着带到巴比伦，在狱中度过余生。他不听先知耶利米的警告，悖逆带来了灾难性的后果。",
