    "star": 0,
    "role": "南国好王 · 本章走错路却蒙怜悯的那一位",
    "relation": "行耶和华眼中看为正的事，却与亚哈结亲、下撒玛利亚结盟；战场上穿王服，一呼喊蒙神保守。",
