    "avoid": "不要与北国亚哈（Ahab，暗利之子，西撒别夫之夫）混淆：亚哈斯是南国犹大王，亚哈是北国第七王，相差约一百二十年；也不要与已有的 isa-07 人物卡「ahaz」合并，本章用独立 id ahaz-2ch28 专指他在代下 28 章的恶王画像。",
