    "star": 1,
    "role": "南国犹大王 · 开殿大复兴的发起者 · 亚哈斯之子",
    "relation": "恶王亚哈斯之子、亚比雅所生；二十五岁登基，作王二十九年；他在元年正月开门，召利未人、献赎罪祭、恢复大卫—迦得—拿单的敬拜秩序。",
