    "avoid": "不要与列王纪下 18–20 章的另外三张希西家卡（hezekiah-2ki18/19/20）混同：本章专记他「开殿、自洁、恢复敬拜」的复兴起点；亚述围城、病得医治、巴比伦使者是后几章的事。也不要把他与北国任何王混淆——北国没有叫希西家的王。",
