    "avoid": "旧约里另有多个同名条目（hezekiah-2ki18/19/20、hezekiah-isa36/37/38/39），本章这个 id 专门对应「招聚全民守逾越节」这一形象，不要与他在亚述围城、病中求寿、向巴比伦使者炫耀财富的形象混为一谈。",
