    "avoid": "旧约另有平行条目（manasseh-2ki21 见王下 21 章）；本章这个 id 专门对应「被掳巴比伦后悔改、归回复位」这一形象，不要与他在王下 21 章只被记恶、不记悔改的简略形象混为一谈。",
