    "role": "祭司兼文士 · 本章认罪祷告的带头人",
    "relation": "他是被亚达薛西王差从波斯回耶路撒冷的祭司；面对百姓娶外邦妻的罪，他以「我们」代全民认罪。",
    "first": "拉7:1",
