    "aka": [
      "祭司",
      "律法教师"
    ],
    "star": 1,
    "role": "祭司·文士 · 本章改革执行者",
    "relation": "他是第九章俯伏祷告的人，也是第十章起来执行的人；被百姓（示迦尼）反过来推着向前，又使祭司长、利未人、众人起誓。",
