    "relation": "他是归回群体的领袖；面对参巴拉、多比雅的嗤笑，他不回嘴，只向上祷告；面对百姓喊累，他部署百姓按宗族带兵器站在低洼处；从那日起他自己和仆人、护兵都不脱衣服，出去打水也带兵器。",
