    "avoid": "不要把他读成靠血气硬打的军事领袖；他的第一反应是 4:4–5 跪下祷告，不是拔刀。他也不是独自硬扛的英雄——他把贵胄、官长、百姓都动员起来，一半作工、一半拿兵器。",
