    "relation": "他是被掳归回群体的世俗领袖；对放债的贵胄官长是斥责者，对挨饿的百姓是体恤者，对神是只求记念我的仆人。与大祭司以利亚实同工修墙，却在本章独自处理内部经济不公。",
