    "star": 1,
    "role": "约伯的三友之一 · 第一轮辩论中第三个、也是最不留情的发言者 · 「受苦必因有罪」公式的极端表达者",
    "relation": "排在以利法（4–5 章）、比勒达（8 章）之后发言；他一上来就封约伯的嘴（2–3 节），直接断言神追讨约伯比他罪孽该得的还少（6 节），又用 13–19 节的悔改应许把恢复建立在「你若除掉罪孽」的条件上。42:7 神亲口定他与另两友为「我说错了」。",
