    "relation": "刚听完琐法在 11 章断言「恶人的指望就是气绝」；本章约伯把三个人一起算进听众席，先反讽他们垄断智慧，再抬眼看走兽飞鸟作证，最后用一首主权诗把神的伟大摆出来反驳他们的因果公式。",
