    "relation": "约伯的朋友，第一轮（伯8章）他还引用列祖的话、还讲「神必不丢弃完全人」（8:20）；本章是他第二次发言，耐心全没了——先嫌约伯话多、把朋友当畜生，再用灯、网、圈套、活扣、惊吓之王、硫磺、根枝、名、后代一连串意象，把约伯正在经历的苦难解释成「恶人该有的结局」，最后下结论「此乃不认识神之人的地步」。",
