    "relation": "布西人，兰族巴拉迦的儿子；在约伯与三友辩论到无言时憋了许久才开口；本章是他第四场、也是最后一场发言的收尾——先自己心战兢，再邀请约伯站立思想，最后亲手把麦克风放下",
