    "key": [
      "诗5:6",
      "诗5:9",
      "诗5:10"
    ],
    "one": "喉咙是敞开的坟墓，嘴里却抹着蜜；大卫不封他们的口，只求神定他们的罪。",
    "avoid": "与 5:5 的「狂傲人」不同：狂傲人明着顶撞，谄媚人用顺从的姿态下刀。",
