    "star": 1,
    "role": "以色列王 · 本篇哀歌与信赖诗的作者",
    "relation": "本篇中他眼见虔诚人断绝、邻舍彼此说谎，便开口求耶和华帮助；他从哀叹人的嘴，转向称赞神炼过七次的话。",
