    "avoid": "篇题只说'大卫的诗，交与伶长，调用第八'，未写明对应他一生中的哪段经历，不要硬套扫罗追杀或押沙龙叛乱；他是哀叹者与信心诗人，不是那一位真正嘴里没有诡诈的义仆。",
