    "avoid": "不要把他读成'打了胜仗就轻松感恩的王'——诗 66 前半明写被试验、进网罗、被车轧头；也不要把这一篇读成'信神就一帆风顺'。他还愿时不牵斑鸠了事，他把最好的肥牛公羊牵来；但真正的祭物不是牛羊，是那一位更大的大卫子孙。",
