    "relation": "诗67篇题未署名，但这一类'交与伶长、用丝弦的乐器'的会众祝福诗，与大卫在代上16将约柜迎回时吩咐伶长歌颂耶和华的经历一脉相承；他是那位带领会众把祭司的祝福反过来向神求的王。",
