    "avoid": "不要把 74 篇完全读成「亚萨本人在 586 年写的」——亚萨是大卫时期人，586 年他已过世数百年；本篇是「亚萨子孙」在被掳时期所作。他不是英雄式的先知，他是一个在废墟里仍敢向神发问的敬拜者。",
