    "avoid": "不要把他与常驻卡「yahweh」当成两位神——这是同一位耶和华在本章的「伸冤与避难」切面，单独建卡只为了让读者记住「诗 94 的耶和华是听见哀声、扶住失脚者的耶和华」；也不要把他读成「等恶人倒台才作高台」——诗 94 说恶人还在夸胜的时候，他已经是高台。",
