    "star": 2,
    "role": "以色列王 · 来 4:7 提到的“大卫的书上”那位说话者",
    "relation": "本章无题注，大卫本人不在场；希伯来书 4:7 说神“在大卫的书上”限定一个“今日”，把这篇诗的警告一直延到教会时代。",
