    "avoid": "不要把亚伯拉罕读成本诗直接出场的人物——本诗二十六节没有提他的名字；但 v22「赐他的仆人以色列为业」背后，是神给亚伯拉罕的约。路加福音 1:55 把这条线点破了。",
