    "role": "以色列王 · 圣殿乐队的编排者",
    "relation": "耶西之子，以色列第二任王；诗 150 未点他的名，但 v3–5 那支角、瑟、琴、鼓、舞、丝弦、箫、钹的乐队，是他当年在耶路撒冷圣殿里亲手组织的编制。",
    "first": "撒上16:1",
    "key": [
      "撒下6:5",
      "撒下6:14",
      "代上25:1-6"
    ],
    "one": "他运约柜进耶路撒冷时在耶和华面前极力跳舞；他又亲手把歌唱的、弹琴的、敲钹的分班排定——诗150那一整支乐队，就是他排出来的。",
    "avoid": "不要把两处「大卫弹琴」混为一谈：撒上 16:23 是他拿琴赶走扫罗身上的恶魔；诗 150 里的瑟、琴、鼓、钹，是他后来在代上 25 章组织的圣殿班赞乐队，不是他一个人独奏的那把琴。",
