    "relation": "她在箴言 1–9 章被拟人化为一位女性：在城门口呼喊（1:20）、在创造之先已被立（8:22–31）；本章她亲自盖房、宰牛、调酒、打发使女，请愚蒙人来吃饼喝酒。新约林前 1:24、1:30 把她等同于基督。",
