    "role": "大卫所立利未歌唱者 ／ 诗 73 的见证人",
    "relation": "亚萨是大卫时代约柜前的歌唱班长（代上 16:5），他的子孙世袭此职；诗 73 以他的名字标题。本篇不是替他立传，而是借他的口把「见恶人亨通而几乎跌倒」的挣扎带到神面前，再记下在圣所里被校正的经过。",
    "first": "代上 16:5",
