    "one": "他三次求「求你使我们回转」，把自己也算进那群转不回来的人里——领唱的人先承认自己需要被神转回。",
    "avoid": "不要把 80 篇读成亚萨本人在北国灭亡现场的亲笔：亚萨是大卫时代人，本篇更可能是「亚萨子孙」在被掳前后所作；也不要把他与尼希米记里守城门的亚萨混为一人。",
