    "avoid": "不要把 82:6「你们是神」读成「人可变神」的根据：那是指审判者按职分承受神的话，第 7 节随即判他们「要死，与世人一样」；也不要以为全篇都是亚萨在说话，1–7 节是神在说话。",
    "tags": [
      "旧约",
      "人物",
      "诗班",
      "作者"
    ],
    "chapters": [
      "psa-82"
    ]
